gab2(){return"\u062a\u064f\u062d\u062a\u0633\u0628 \u0627\u0644\u0639\u0645\u0648\u0644\u0629 \u0639\u0644\u0649 \u062d\u0627\u0644\u0627\u062a \u0647\u0630\u0627 \u0627\u0644\u0645\u0648\u0638\u0641 \u0645\u0646 \u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0630\u064a \u064a\u0644\u064a \u0647\u0630\u0627 \u0627\u0644\u064a\u0648\u0645 \u0625\u0644\u0649 \u0646\u0641\u0633 \u0627\u0644\u064a\u0648\u0645 \u0645\u0646 \u0627\u0644\u0634\u0647\u0631 \u0627\u0644\u062a\u0627\u0644\u064a (\u0645\u062b\u0644\u0627\u064b 4 = \u0645\u0646 5 \u0625\u0644\u0649 4). \u0627\u062a\u0631\u0643\u0647 \u0641\u0627\u0631\u063a\u0627\u064b \u0644\u0644\u0634\u0647\u0631 \u0627\u0644\u0645\u064a\u0644\u0627\u062f\u064a."},
gUe(){return"\u0627\u0644\u0639\u0645\u0648\u0644\u0629"},
