gVb(){return"\u0686\u0627\u067e\u06a9\u0631\u062f\u0646"},
gVc(){return"\u0634\u06ce\u0648\u06d5\u06cc \u0628\u06d5\u06b5\u06af\u06d5\u0646\u0627\u0645\u06d5 \u0686\u0627\u067e\u06a9\u0631\u0627\u0648\u06d5\u06a9\u0627\u0646 \u0628\u06c6 \u0626\u06d5\u0645 \u0644\u0642\u06d5."},
